mapper.select:
SELECT vehicle_id,plate_no,license_type,enabled FROM training_vehicle
enabled = #{enabled}
ORDER BY vehicle_id

mapper.update:
UPDATE training_vehicle
SET plate_no = #{plateNo}, license_type = #{licenseType}, enabled = #{enabled}
WHERE vehicle_id = #{vehicleId}

UPDATE training_booking
SET status = 'CANCELLED', cancelled_at = #{cancelledAt}
WHERE booking_id = #{bookingId} AND status IN ('PENDING','ASSIGNED')

mapper.select:
SELECT COUNT(*)
FROM training_booking
WHERE status IN ('PENDING','ASSIGNED','COMPLETED')
  AND planned_start < #{plannedEnd}
  AND planned_end > #{plannedStart}
  AND (
    (#{studentUserId} IS NOT NULL AND student_user_id = #{studentUserId})
    OR (#{coachUserId} IS NOT NULL AND coach_user_id = #{coachUserId})
    OR (#{vehicleId} IS NOT NULL AND vehicle_id = #{vehicleId})
  )
AND booking_id <> #{excludeBookingId}

mapper.update:
UPDATE training_booking
SET status = 'CANCELLED', cancelled_at = #{now}
WHERE student_user_id = #{studentUserId}
  AND status IN ('PENDING','ASSIGNED')
  AND planned_start > #{now}

mapper.select:
SELECT COUNT(*) FROM training_booking
WHERE student_user_id = #{studentUserId}
  AND status IN ('PENDING','ASSIGNED')
  AND planned_start <= #{now}
  AND planned_end > #{now}

SELECT 
FROM training_booking

    student_user_id = #{studentUserId}
    AND coach_user_id = #{coachUserId}
    AND status = #{status}

ORDER BY planned_start DESC, booking_id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM training_booking

    student_user_id = #{studentUserId}
    AND coach_user_id = #{coachUserId}
    AND status = #{status}
